  public function executeUpdate()
  {
    if (!$this->getRequestParameter('catalogo_id'))
    {
      $catalogo = new Catalogo();
      $documentacion   = new Documentacion();
    }
    else
    {
      $catalogo = CatalogoPeer::retrieveByPk($this->getRequestParameter('catalogo_id'));
      $documentacion = DocumentacionPeer::retrieveByPk($catalogo->getDocumentacionId());
      $this->forward404Unless($catalogo);
    }
    
    //$documentacion->setDocumentacionId($this->getRequestParameter('documentacion_id'));
	$documentacion->setIdiomaId($this->getRequestParameter('idioma_id'));
	$documentacion->setEstadodocumentacionId(1);
	$documentacion->setTipodocumentacionId(2);//id del modulo de catalogo
	$documentacion->setTitulo($this->getRequestParameter('titulo'));
	$documentacion->setOtraInformacionTitulo($this->getRequestParameter('otra_informacion_titulo'));
	$documentacion->setPrimeraMencionResponsabilidad($this->getRequestParameter('primera_mencion_responsabilidad'));
	$documentacion->setMencionResponsabilidad($this->getRequestParameter('mencion_responsabilidad'));
	$documentacion->setNumeroClasificacion($this->getRequestParameter('numero_clasificacion'));
	$documentacion->setDescriptoresTematicos($this->getRequestParameter('descriptores_tematicos'));
	$documentacion->setCodigoBarras($this->getRequestParameter('codigo_barras'));
	$documentacion->setUbicacion($this->getRequestParameter('ubicacion'));
	$documentacion->save();	
	    
    //$catalogo->setCatalogoId($this->getRequestParameter('catalogo_id'));
    $catalogo->setEspecialidadId($this->getRequestParameter('especialidad_id'));
    if($this->getRequestParameter('documentacion_id')){
    	$catalogo->setDocumentacionId($this->getRequestParameter('documentacion_id'));
    }else{
		$catalogo->setDocumentacionId($documentacion->getDocumentacionId());
	}    
    $catalogo->setMencionEdicion($this->getRequestParameter('mencion_edicion'));
    $catalogo->setVersion($this->getRequestParameter('version'));
    $catalogo->setPaginacion($this->getRequestParameter('paginacion'));
    $catalogo->setIlustraciones($this->getRequestParameter('ilustraciones', 0));
    $catalogo->setVolumen($this->getRequestParameter('volumen'));
    $catalogo->setMaterialComplementario($this->getRequestParameter('material_complementario'));
    $catalogo->setIssn($this->getRequestParameter('issn'));
    $catalogo->setNotasContenido($this->getRequestParameter('notas_contenido'));

    $catalogo->save();
    
    if($this->getRequestParameter('catalogo_id')){
	  $this->userEdit($this->getRequestParameter('idUser'),$documentacion->getDocumentacionId()); 	
	}else{
	  $this->userDoc($this->getRequestParameter('idUser'),$documentacion->getDocumentacionId());	
	}
	
    return $this->redirect($this->getRequest()->getScriptName().'/catalogo/show?catalogo_id='.$catalogo->getCatalogoId().'&documentacion_id='.$documentacion->getDocumentacionId());
    
	//return $this->redirect($this->getRequest()->getScriptName().'/catalogo/show?catalogo_id='.$catalogo->getCatalogoId());
  }
  
